#[verus]
fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // Ensure the length of the array does not exceed the maximum for 8-bit signed integers
    assert!(arr.len() <= 255);

    let mut result = Vec::with_capacity(arr.len());
    
    // Iterate over each element in the input array
    for &value in arr.iter() {
        // If min_val <= max_val, clip the value to the range [min_val, max_val]
        if min_val <= max_val {
            if value < min_val {
                result.push(min_val);
            } else if value > max_val {
                result.push(max_val);
            } else {
                result.push(value);
            }
        } else {
            // If min_val > max_val, all elements in the result are equal to max_val
            result.push(max_val);
        }
    }

    // Ensure the result has the same length as the input array
    assert!(result.len() == arr.len());
    
    result
}